use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Domain\ValueObject\Holder\SmtpOutboundConfigMaxRetriesAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SmtpOutboundConfigMaxRetriesAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SmtpOutboundConfigMaxRetriesAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getMaxRetries returns null on a freshly created holder.
         */
        public function testMaxRetriesNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithSmtpOutboundConfigMaxRetriesAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isMaxRetriesAssigned());
            $this->assertNull($holder->getMaxRetries());
        }
}
class ImplWithSmtpOutboundConfigMaxRetriesAttributeHolderUnitTest
